function weaponJoins(items, kind, u, who){
  if(!u.gear) return null;
  const own = i => who == null || whoOfLine(u, i) === who;
  const mine = u.gear.map((g, i) => i).filter(own);
  const short = i => u.models[i].replace(/^\d+× /, '').replace(/ w\/.*$/, '');
  // a divider names a models line in full when another line shares its short name ("Tankbusta w/ Two Busta Rokkit Launchas")
  const nameOf = i => mine.some(j => j !== i && short(j) === short(i)) ? u.models[i].replace(/^\d+× /, '') : short(i);
  const lines = mine.map(i => ({ i, name:nameOf(i), has:items.filter(it => u.gear[i].includes(itemName(it))) })).filter(l => l.has.length);
  // a weapon only one models line of one model has, in a squad of mixed loadouts: that model's name on its row (the weapon tells which one)
  if(lines.length > 1) for(const it of items){ const ls = lines.filter(l => l.has.includes(it)); if(!it.n && !it.carrier && ls.length === 1 && /^1× /.test(u.models[ls[0].i])) it.carrier = short(ls[0].i); }
  const big = hasKw(u, 'Monster') || hasKw(u, 'Vehicle');
  let order = [];
  for(const l of lines) for(const it of l.has) if(!order.includes(it)) order.push(it);
  for(const it of items) if(!order.includes(it)) order.push(it);
  const joins = order.map(() => null);
  const scopeOf = (ls, its) => { const carry = lines.filter(l => its.some(it => l.has.includes(it))); return ls.length < carry.length ? [...new Set(ls.map(l => l.name))].join(', ') : ''; };
  if(kind === 'ranged'){
    order = order.filter(it => !isCQ(it)).concat(order.filter(isCQ));
    const both = big ? [] : lines.filter(l => l.has.some(isCQ) && l.has.some(it => !isCQ(it)));
    const k = order.findIndex(isCQ);
    if(!both.length || k <= 0) return { order, joins };
    // one divider between all the other guns and all the [CLOSE-QUARTERS] ones: only when every model with these has both
    if(scopeOf(both, order)) return null;
    joins[k] = { t:'or', rule:'Close-quarters', scope:'when using another shooting type' };   // in close-quarters shooting: those weapons only
    return { order, joins };
  }
  order = order.filter(it => !isEA(it)).concat(order.filter(isEA));
  for(let k = 1; k < order.length; k++){
    const a = order[k - 1], b = order[k];
    // "+": named when not every model with this weapon or one of the weapons above it has the two together
    if(isEA(b)){ const ls = lines.filter(l => l.has.includes(b) && l.has.some(it => !isEA(it))); if(ls.length) joins[k] = { t:'+', rule:'EXTRA ATTACKS', scope:scopeOf(ls, [b].concat(order.filter(it => !isEA(it)))) }; continue; }
    const ls = lines.filter(l => l.has.includes(a) && l.has.includes(b));
    if(ls.length) joins[k] = { t:'or', rule:'Select Weapons', scope:scopeOf(ls, [a, b]) };
  }
  // every model's weapons to pick from must be neighbours joined by "or"
  for(const l of lines){
    const main = l.has.filter(it => !isEA(it)); if(main.length < 2) continue;
    const ix = main.map(it => order.indexOf(it)).sort((x, y) => x - y);
    if(ix[ix.length - 1] - ix[0] !== main.length - 1) return null;
  }
  return { order, joins };
}
